def binary_search(nums, target):
    lo, hi = 0, len(nums) - 1
    steps = 0
    while lo <= hi:
        steps += 1
        mid = (lo + hi) // 2
        if nums[mid] == target:
            return mid, steps
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1, steps


nums = [3, 8, 15, 21, 34, 42, 57, 63, 78, 91]
for target in [57, 40]:
    index, steps = binary_search(nums, target)
    print(f"{target}: index {index} in {steps} steps")

evens = list(range(0, 2_000_000, 2))
index, steps = binary_search(evens, 1_234_568)
print(f"{len(evens):,} items: index {index} in {steps} steps")

