def find_word(words, target):
    lo, hi = 0, len(words) - 1
    steps = 0
    while lo <= hi:
        steps += 1
        mid = (lo + hi) // 2
        if words[mid] == target:
            return mid, steps
        if words[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1, steps


words = [
    "apple", "banana", "cherry", "grape", "kiwi",
    "lemon", "mango", "peach", "plum",
]
for target in ["mango", "fig"]:
    index, steps = find_word(words, target)
    print(f"{target}: index {index} in {steps} steps")
